import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layer_norm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void reduce_kernel(const float* __restrict__ input,
                               float* __restrict__ sum_out,
                               float* __restrict__ sqsum_out,
                               int inner_size,
                               int chunk_elems) {
    int n = blockIdx.x;
    int c = blockIdx.y;
    int start = c * chunk_elems;
    int end = start + chunk_elems;
    if (end > inner_size) end = inner_size;
    const float* x = input + (size_t)n * inner_size;
    float sum = 0.f;
    float sqsum = 0.f;
    int vec_start = start / 4;
    int vec_end = end / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x);
    for (int i = vec_start + threadIdx.x; i < vec_end; i += blockDim.x) {
        float4 v = x4[i];
        sum += v.x + v.y + v.z + v.w;
        sqsum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    for (int i = vec_end * 4 + threadIdx.x; i < end; i += blockDim.x) {
        float v = x[i];
        sum += v;
        sqsum += v * v;
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    __shared__ float ssum[32];
    __shared__ float ssqsum[32];
    int lane = threadIdx.x & 31;
    int warpId = threadIdx.x >> 5;
    if (lane == 0) {
        ssum[warpId] = sum;
        ssqsum[warpId] = sqsum;
    }
    __syncthreads();
    int numWarps = (blockDim.x + 31) >> 5;
    if (warpId == 0) {
        sum = (lane < numWarps) ? ssum[lane] : 0.f;
        sqsum = (lane < numWarps) ? ssqsum[lane] : 0.f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
            sqsum += __shfl_down_sync(mask, sqsum, offset);
        }
        if (lane == 0) {
            atomicAdd(&sum_out[n], sum);
            atomicAdd(&sqsum_out[n], sqsum);
        }
    }
}
__global__ void finalize_kernel(const float* __restrict__ sum,
                                 const float* __restrict__ sqsum,
                                 float* __restrict__ mean_out,
                                 float* __restrict__ invstd_out,
                                 int inner_size,
                                 float eps,
                                 int N) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    if (n < N) {
        float m = sum[n] / inner_size;
        float var = sqsum[n] / inner_size - m * m;
        if (var < 0.f) var = 0.f;
        mean_out[n] = m;
        invstd_out[n] = rsqrtf(var + eps);
    }
}
__global__ void normalize_kernel(const float* __restrict__ input,
                                  const float* __restrict__ gamma,
                                  const float* __restrict__ beta,
                                  const float* __restrict__ mean_arr,
                                  const float* __restrict__ invstd_arr,
                                  float* __restrict__ output,
                                  int inner_size,
                                  int64_t total) {
    int64_t vec_size_row = inner_size / 4;
    int64_t total_vec = total / 4;
    const float4* x4 = reinterpret_cast<const float4*>(input);
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    float4* out4 = reinterpret_cast<float4*>(output);
    for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < total_vec; i += (int64_t)blockDim.x * gridDim.x) {
        int64_t row = i / vec_size_row;
        int64_t col = i % vec_size_row;
        float mean = mean_arr[row];
        float invstd = invstd_arr[row];
        float4 v = x4[i];
        float4 g = gamma4[col];
        float4 b = beta4[col];
        float4 o;
        o.x = (v.x - mean) * invstd * g.x + b.x;
        o.y = (v.y - mean) * invstd * g.y + b.y;
        o.z = (v.z - mean) * invstd * g.z + b.z;
        o.w = (v.w - mean) * invstd * g.w + b.w;
        out4[i] = o;
    }
    int64_t tail_start = total_vec * 4;
    for (int64_t i = tail_start + (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < total; i += (int64_t)blockDim.x * gridDim.x) {
        int64_t row = i / inner_size;
        int64_t col = i % inner_size;
        float mean = mean_arr[row];
        float invstd = invstd_arr[row];
        float v = input[i];
        output[i] = (v - mean) * invstd * gamma[col] + beta[col];
    }
}
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    auto x_contig = x.contiguous();
    auto gamma_contig = gamma.contiguous();
    auto beta_contig = beta.contiguous();
    int64_t inner_size = gamma_contig.numel();
    int64_t total = x_contig.numel();
    int64_t N = total / inner_size;
    auto output = torch::empty_like(x_contig);
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    auto sum_buf = torch::zeros({N}, options);
    auto sqsum_buf = torch::zeros({N}, options);
    auto mean_buf = torch::empty({N}, options);
    auto invstd_buf = torch::empty({N}, options);
    int threads = 256;
    int64_t elements_per_chunk = 8192;
    int64_t chunks_per_row = (inner_size + elements_per_chunk - 1) / elements_per_chunk;
    if (chunks_per_row < 1) chunks_per_row = 1;
    dim3 grid_reduce((unsigned int)N, (unsigned int)chunks_per_row);
    size_t shared_mem = 2 * threads * sizeof(float);
    reduce_kernel<<<grid_reduce, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        sum_buf.data_ptr<float>(),
        sqsum_buf.data_ptr<float>(),
        (int)inner_size,
        (int)elements_per_chunk
    );
    int finalize_threads = 256;
    int finalize_blocks = (int)((N + finalize_threads - 1) / finalize_threads);
    finalize_kernel<<<finalize_blocks, finalize_threads>>>(
        sum_buf.data_ptr<float>(),
        sqsum_buf.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        (int)inner_size,
        (float)eps,
        (int)N
    );
    int norm_threads = 256;
    int64_t total_vec = total / 4;
    int64_t norm_blocks64 = (total_vec + norm_threads - 1) / norm_threads;
    if (norm_blocks64 < 1) norm_blocks64 = 1;
    if (norm_blocks64 > 65535) norm_blocks64 = 65535;
    int norm_blocks = (int)norm_blocks64;
    normalize_kernel<<<norm_blocks, norm_threads>>>(
        x_contig.data_ptr<float>(),
        gamma_contig.data_ptr<float>(),
        beta_contig.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        invstd_buf.data_ptr<float>(),
        output.data_ptr<float>(),
        (int)inner_size,
        total
    );
    return output;
}
"""

layer_norm_header = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layer_norm_ext = load_inline(
    name="layer_norm_ext",
    cpp_sources=layer_norm_header,
    cuda_sources=layer_norm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.to(x.device)
        bias = self.bias.to(x.device)
        return layer_norm_ext.layer_norm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2)
    return [x]


def get_init_inputs():
    return [(features, dim1, dim2)]

